#include "rf_private.h"
#include "bitfield.h"
#include "rftd2.h"
#include "prog.h"

/*==========================================================================*/
/*      D E F I N E S  -  E N U M E R A T I O N S  -  T Y P E D E F S       */
/*==========================================================================*/

/*==========================================================================*/
/*                  F U N C T I O N   P R O T O T Y P E S                   */
/*==========================================================================*/

/*==========================================================================*/
/*                            V A R I A B L E S                             */
/*==========================================================================*/

/*==========================================================================*/
/*                 F U N C T I O N   D E F I N I T I O N S                  */
/*==========================================================================*/
void rf_icon_clr (Rf_Icon_Def icon, Boolean update)
{
  	// set icon you want
  	bitfield_wr(rf_data.icon.bit , icon , icon , FALSE );
	bitfield_wr(rf_support.icon.bit , icon , icon , TRUE );

  	// update rf
	if(update)
	{
		rf_update() ;
	}

	if(prog_retrieve_option(FEAT_RF_OUTPUT)== RF_TD2 )	// always update when in rftd2
    {  		 
	  	rftd2_update(RFTD2_UPDATE_UPON_CHANGE) ;
	}
}
